WITH filtered AS (SELECT *, pressure + humidity AS pressure_plus_humidity, CASE WHEN humidity >= 63 THEN 'High' WHEN humidity >= 34 THEN 'Medium' ELSE 'Low' END AS humidity_level FROM device_readings WHERE reading_ts >= DATE '2025-09-01' AND humidity IS NULL) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, device_code, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, COUNT(DISTINCT device_code) AS distinct_device_codes, SUM(CASE WHEN device_code = 'DV-02' THEN humidity ELSE 0 END) AS dv_02_humidity, GROUPING(DATE_TRUNC('DAY', reading_ts)) AS grouping_level FROM filtered GROUP BY GROUPING SETS ((DATE_TRUNC('DAY', reading_ts), device_code), (DATE_TRUNC('DAY', reading_ts)), ()) ORDER BY activity_day DESC NULLS FIRST;
